CREATE   PROCEDURE [synapse_ce].[usp_Insert_rics_survey]
AS
BEGIN
	INSERT INTO [synapse_ce].[rics_survey]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[rics_code],
		[rics_failurethreshold],
		[rics_introduction],
		[rics_introduction_entitytype],
		[rics_introductionname],
		[rics_languagecode],
		[rics_name],
		[rics_publicationstate],
		[rics_replacessurvey],
		[rics_replacessurvey_entitytype],
		[rics_replacessurveyname],
		[rics_surveyid],
		[rics_surveytype],
		[rics_totalanswersrequired],
		[rics_totalpages],
		[rics_totalquestions],
		[rics_validfrom],
		[rics_validto],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[rics_code],
		stg.[rics_failurethreshold],
		stg.[rics_introduction],
		stg.[rics_introduction_entitytype],
		stg.[rics_introductionname],
		stg.[rics_languagecode],
		stg.[rics_name],
		stg.[rics_publicationstate],
		stg.[rics_replacessurvey],
		stg.[rics_replacessurvey_entitytype],
		stg.[rics_replacessurveyname],
		stg.[rics_surveyid],
		stg.[rics_surveytype],
		stg.[rics_totalanswersrequired],
		stg.[rics_totalpages],
		stg.[rics_totalquestions],
		stg.[rics_validfrom],
		stg.[rics_validto],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[rics_survey] stg
		LEFT JOIN [synapse_ce].[rics_survey] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
